        <div class="panel"><h5>Contacts</h5><div id="contactsList"></div></div><div class="panel"><h5>Recent Leads</h5><div id="leadsList"></div></div><div class="panel"><h5>Recent Deals</h5><div id="dealsList"></div></div>
