<script src="{{ asset('vendors/js/vendor.bundle.base.js') }}"></script><script>
    const companyId={{ (int) $companyId }};const esc=v=>$('<div>').text(v??'').html();const empty=label=>`<p class="text-muted mb-0">No ${label} linked yet.</p>`;
    $.get("{{ url('companies') }}/"+companyId+'/detail',r=>{const c=r.data;$('#companyName').text(c.name);$('#companySubtitle').text([c.industry,c.status].filter(Boolean).join(' · '));$('#contactCount').text(c.contacts_count);$('#leadCount').text(c.leads_count);$('#dealCount').text(c.deals_count);$('#companyInfo').html(`<div class="field"><span>Owner</span><strong>${esc(c.owner?.name||'Unassigned')}</strong></div><div class="field"><span>Email</span><strong>${esc(c.email||'-')}</strong></div><div class="field"><span>Phone</span><strong>${esc(c.phone||'-')}</strong></div><div class="field"><span>Website</span><strong>${c.website?`<a href="${esc(c.website)}" target="_blank" rel="noopener">Visit</a>`:'-'}</strong></div><div class="field"><span>Location</span><strong>${esc([c.city,c.state,c.country].filter(Boolean).join(', ')||'-')}</strong></div><div class="field"><span>GST</span><strong>${esc(c.gst_number||'-')}</strong></div>`);$('#contactsList').html(c.contacts.length?c.contacts.map(x=>`<div class="related-row"><strong>${esc(x.name)}</strong>${x.is_primary?' <i class="fa fa-star text-warning"></i>':''}<br><span class="meta">${esc(x.designation||'')} ${esc(x.email||x.phone||'')}</span></div>`).join(''):empty('contacts'));$('#leadsList').html(c.leads.length?c.leads.map(x=>`<div class="related-row"><a href="{{ url('leads') }}/${x.id}"><strong>${esc(x.name)}</strong></a><span class="float-right meta">${esc(x.lead_status)}</span><br><span class="meta">Owner: ${esc(x.assigned_user?.name||'Unassigned')}</span></div>`).join(''):empty('leads'));$('#dealsList').html(c.deals.length?c.deals.map(x=>`<div class="related-row"><a href="{{ url('deals') }}/${x.id}"><strong>${esc(x.name)}</strong></a><span class="float-right meta">${esc(x.currency||'')} ${Number(x.amount||0).toLocaleString('en-IN')}</span><br><span class="meta">${esc(x.stage?.name||x.status)}</span></div>`).join(''):empty('deals'))}).fail(()=>$('#companyName').text('Company not found'));
</script></body></html>
